def ops_per_sec_comparison(n_buckets: int, qps: int) -> dict[str, int]:
    if n_buckets <= 0 or qps <= 0:
        raise ValueError('Buckets and QPS must be positive')
    bit_steps = n_buckets.bit_length()
    return {'naive_prefix_ops_sec': n_buckets * qps, 'fenwick_ops_sec': bit_steps * qps}

def memory_mb(n: int, bytes_per_val: int = 8) -> dict[str, float]:
    if n <= 0:
        raise ValueError('n must be positive')
    return {
        'fenwick_mb': round(((n + 1) * bytes_per_val) / 1e6, 2),
        'segment_tree_mb': round((4 * n * bytes_per_val) / 1e6, 2),
    }

def price_to_tick_index(price_cents: int, min_price_cents: int, tick_cents: int, max_ticks: int) -> int:
    if tick_cents <= 0:
        raise ValueError('tick_cents must be positive')
    idx = (price_cents - min_price_cents) // tick_cents + 1
    if not (1 <= idx <= max_ticks):
        raise ValueError(f'Price {price_cents} maps outside [1, {max_ticks}]')
    return idx

def range_volume(bit: FenwickTree, l_tick: int, r_tick: int) -> int:
    if l_tick > r_tick or l_tick < 1 or r_tick > bit.n:
        raise ValueError('Invalid tick range')
    return bit.prefix_sum(r_tick) - bit.prefix_sum(l_tick - 1)

import math

def query_quantile_bucket(tree: list[int], n: int, quantile: float) -> int:
    if not (0.0 < quantile <= 1.0):
        raise ValueError('quantile must be in (0, 1]')
    total = 0
    idx = n
    while idx > 0:
        total += tree[idx]
        idx -= idx & -idx
    if total == 0:
        return 0
    target = math.ceil(total * quantile)
    return kth_order_statistic(tree, n, target)

def select_ring_slot(epoch_sec: int, window_sec: int = 60) -> int:
    if epoch_sec < 0 or window_sec <= 0:
        raise ValueError('epoch_sec >= 0 and window_sec > 0 required')
    return epoch_sec % window_sec
